#include <iostream>

bool menor_valor(int dato, unsigned int limite) {
    return static_cast<unsigned int>(dato) < limite;
}

int main() {
    int dato = 0;
    int limite_leido = 0;

    if (!(std::cin >> dato >> limite_leido)
        || dato < -30000 || dato > 30000
        || limite_leido < 0 || limite_leido > 30000) {
        return 1;
    }

    const unsigned int limite = static_cast<unsigned int>(limite_leido);
    std::cout << "Menor=" << menor_valor(dato, limite) << '\n';

    return 0;
}

